def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple[str, str, str, int]] = []
    rejected: list[int] = []

    def parse_amount(token: str) -> int:
        if token and token.isascii() and token.isdigit():
            return int(token)
        return -1

    for idx, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0]
        n_parts = len(parts)

        if verb == "open" and n_parts == 3:
            acct = parts[1]
            amount = parse_amount(parts[2])
            if amount >= 0 and acct not in balances:
                balances[acct] = amount
                history.append(("open", acct, "", 0))
            else:
                rejected.append(idx)

        elif verb == "deposit" and n_parts == 3:
            acct = parts[1]
            amount = parse_amount(parts[2])
            if amount > 0 and acct in balances:
                balances[acct] += amount
                history.append(("deposit", acct, "", amount))
            else:
                rejected.append(idx)

        elif verb == "withdraw" and n_parts == 3:
            acct = parts[1]
            amount = parse_amount(parts[2])
            if amount > 0 and acct in balances and acct not in frozen and balances[acct] >= amount:
                balances[acct] -= amount
                history.append(("withdraw", acct, "", amount))
            else:
                rejected.append(idx)

        elif verb == "transfer" and n_parts == 4:
            src, dst = parts[1], parts[2]
            amount = parse_amount(parts[3])
            if (
                amount > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amount
            ):
                balances[src] -= amount
                balances[dst] += amount
                history.append(("transfer", src, dst, amount))
            else:
                rejected.append(idx)

        elif verb == "freeze" and n_parts == 2:
            acct = parts[1]
            if acct in balances and acct not in frozen:
                frozen.add(acct)
                history.append(("freeze", acct, "", 0))
            else:
                rejected.append(idx)

        elif verb == "unfreeze" and n_parts == 2:
            acct = parts[1]
            if acct in balances and acct in frozen:
                frozen.remove(acct)
                history.append(("unfreeze", acct, "", 0))
            else:
                rejected.append(idx)

        elif verb == "undo" and n_parts == 1:
            if not history:
                rejected.append(idx)
            else:
                h_verb, a, b, amount = history.pop()
                if h_verb == "open":
                    del balances[a]
                elif h_verb == "deposit":
                    balances[a] -= amount
                elif h_verb == "withdraw":
                    balances[a] += amount
                elif h_verb == "transfer":
                    balances[a] += amount
                    balances[b] -= amount
                elif h_verb == "freeze":
                    frozen.remove(a)
                elif h_verb == "unfreeze":
                    frozen.add(a)

        else:
            rejected.append(idx)

    return balances, rejected
